SELECT  json_build_object('aggregate', json_build_object('sum', json_build_object('rating', sum("_root"."root.pg.rating" ) ), 'avg', json_build_object('rating', avg("_root"."root.pg.rating" ) ), 'min', json_build_object('name', min("_root"."root.pg.name" ), 'nickname', min("_root"."root.pg.nickname" ) ), 'max', json_build_object('name', max("_root"."root.pg.name" ), 'nickname', max("_root"."root.pg.nickname" ) ) ) ) AS "root" FROM  (SELECT  "_root.base"."rating" AS "root.pg.rating", "_root.base"."name" AS "root.pg.name", "_root.base"."nickname" AS "root.pg.nickname" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')     ) AS "_root.base"      ) AS "_root"
